import assert from "node:assert/strict";
import { test } from "node:test";
import { WORLD_PATH, WORLD_WIDTH, WORLD_HEIGHT, project } from "../lib/world-map";
import { clusterTechnicians } from "../components/TechnicianMap";
import { TECHNICIANS } from "../lib/technicians";

/*
 * The world map on the repair page.
 *
 * lib/world-map.ts is generated by scripts/build-world-map.mjs and
 * committed, so nothing regenerates it on the way to production. That
 * makes it exactly the kind of file that can rot unnoticed, and these
 * are the checks that would have caught what went wrong while it was
 * being built.
 */

/** Every subpath in the committed outline, as lists of points. */
function subpaths(): Array<Array<[number, number]>> {
  return WORLD_PATH.split("M")
    .filter(Boolean)
    .map((piece) =>
      piece
        .replace(/Z$/, "")
        .split("L")
        .map((pair) => pair.split(" ").map(Number) as [number, number]),
    );
}

test("the outline is real geography, inside its frame", () => {
  const paths = subpaths();
  assert.ok(paths.length > 50, `expected the continents and the larger islands, got ${paths.length}`);

  for (const points of paths) {
    assert.ok(points.length >= 3, "a subpath of fewer than three points draws nothing");
    for (const [x, y] of points) {
      assert.ok(Number.isFinite(x) && Number.isFinite(y), "every coordinate parses");
      /* A little slack: rings are clipped to the frame, not to the pixel. */
      assert.ok(x >= -1 && x <= WORLD_WIDTH + 1, `x ${x} is inside the frame`);
      assert.ok(y >= -1 && y <= WORLD_HEIGHT + 1, `y ${y} is inside the frame`);
    }
  }
});

test("no stroke runs across the map", () => {
  /*
   * The regression this exists for. Natural Earth cuts its polygons at
   * the antimeridian, so four rings here run up one side of the
   * dateline at +180 and resume at -180. Joined rather than split,
   * each drew a line clean across the world: one through the Pacific
   * at the latitude of Fiji, one through the Arctic, and one from
   * Afro-Eurasia. They are faint and easy to miss in a screenshot.
   */
  const longest = Math.max(
    ...subpaths().flatMap((points) =>
      points.slice(1).map((p, i) => Math.abs(p[0] - points[i]![0])),
    ),
  );
  assert.ok(
    longest < WORLD_WIDTH * 0.5,
    `a single segment spans ${longest.toFixed(0)} of ${WORLD_WIDTH} units across`,
  );
});

test("a coordinate lands where it should", () => {
  const equator = project(0, 0);
  assert.equal(Math.round(equator.x), WORLD_WIDTH / 2, "0°E is the middle of the frame");

  /* North of the equator is above the middle of a frame that runs
     84°N to 56°S, and east is to the right of west. */
  const london = project(51.5, -0.13);
  const sydney = project(-33.87, 151.21);
  assert.ok(london.y < equator.y, "London is north of the equator");
  assert.ok(sydney.y > equator.y, "Sydney is south of it");
  assert.ok(sydney.x > london.x, "Sydney is east of London");
});

test("every placed technician is on exactly one mark", () => {
  const placed = TECHNICIANS.filter((t) => t.place);
  const clusters = clusterTechnicians(TECHNICIANS);
  const shown = clusters.flatMap((c) => c.people.map((p) => p.name));

  assert.equal(shown.length, new Set(shown).size, "nobody appears on two marks");
  assert.deepEqual(
    [...shown].sort(),
    placed.map((t) => t.name).sort(),
    "every technician with coordinates is on the map, and nobody without them is",
  );
});

test("no two marks overlap", () => {
  /*
   * The reason the marks are clustered at all: four North American
   * workshops sit 1 to 23 units apart on a map of the world, so
   * separate marks for them overlapped and whichever drew last took
   * the clicks meant for the others.
   *
   * 18 units is where that starts: at the width of the reading column
   * the map draws at about 0.75 scale, so 18 units is ~13 px against
   * marks 16 px across. Anything closer and the two circles cover each
   * other's centres.
   */
  const clusters = clusterTechnicians(TECHNICIANS);
  for (let i = 0; i < clusters.length; i++) {
    for (let j = i + 1; j < clusters.length; j++) {
      const a = clusters[i]!;
      const b = clusters[j]!;
      const apart = Math.hypot(a.x - b.x, a.y - b.y);
      assert.ok(
        apart >= 18,
        `marks for ${a.people[0]!.name} and ${b.people[0]!.name} are ${apart.toFixed(1)} apart`,
      );
    }
  }
});

test("a mark sits among the people it stands for", () => {
  for (const cluster of clusterTechnicians(TECHNICIANS)) {
    for (const person of cluster.people) {
      const { x, y } = project(person.place!.lat, person.place!.lon);
      assert.ok(
        Math.hypot(cluster.x - x, cluster.y - y) <= 24,
        `${person.name} is further from its own mark than the clustering distance`,
      );
    }
  }
});
